3	// Host API 1.0's readContext names the focused workspace's branch and terminals but not its path.
4	// A terminal handle identifies the workspace exactly; branch plus name is the fallback when it has none.
5	export async function resolveFocusedWorkspace(orca, { signal } = {}) {
6	  const context = await orca.host.call('workspace.readContext', {}, { signal })
7	  if (!context) return { context: null, path: null, via: 'none', candidates: [] }
8	  const [terminal] = context.terminals
9	  if (terminal) {
10	    const result = await orcaCli(['terminal', 'show', '--terminal', terminal.id], { signal })
11	    const path = (result.terminal ?? result).worktreePath
12	    if (path) return { context, path, via: 'terminal', candidates: [path] }
13	  }
14	  const { worktrees } = await orcaCli(['worktree', 'list', '--limit', '500'], { signal })
15	  const candidates = matchWorktrees(worktrees, context).map((worktree) => worktree.path)
16	  return { context, path: candidates.length === 1 ? candidates[0] : null, via: 'branch', candidates }
17	}
18	
19	// Orca's CLI reports full refs; readContext reports short branch names.
20	export function shortBranch(ref = '') {
21	  return ref.replace(/^refs\/heads\//, '')
22	}
23	
24	export function matchWorktrees(worktrees, { branch, displayName }) {
25	  return worktrees.filter(
26	    (worktree) =>
27	      !worktree.isArchived && shortBranch(worktree.branch) === branch && worktree.displayName === displayName
28	  )
29	}
